#include <bits/stdc++.h>
using namespace std;

int main() {
    string raw, data;
    char chunk[1 << 16];
    for (size_t got; (got = fread(chunk, 1, sizeof chunk, stdin)) > 0;) raw.append(chunk, got);
    // Treat CRLF and lone CR as newlines, like text-mode input.
    data.reserve(raw.size());
    for (size_t i = 0; i < raw.size(); i++) {
        if (raw[i] == '\r') { data += '\n'; if (i + 1 < raw.size() && raw[i + 1] == '\n') i++; }
        else data += raw[i];
    }
    string().swap(raw);
    if (!data.empty() && data.back() == '\n') data.pop_back();
    vector<string_view> lines;
    for (size_t start = 0;;) {
        size_t end = data.find('\n', start);
        if (end == string::npos) { lines.emplace_back(data.data() + start, data.size() - start); break; }
        lines.emplace_back(data.data() + start, end - start);
        start = end + 1;
    }
    long long n = stoll(string(lines[0]));
    size_t last = min<size_t>(lines.size(), 1 + n);
    unordered_map<string_view, int> counts;
    counts.reserve(2 * last);
    for (size_t i = 1; i < last; i++) counts[lines[i]]++;
    string_view answer;
    for (size_t i = 1; i < last; i++)
        if (counts[lines[i]] == 1) { answer = lines[i]; break; }
    fwrite(answer.data(), 1, answer.size(), stdout);
    putchar('\n');
}

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        // Latin-1 keeps every byte as one char; CRLF and lone CR count as newlines.
        String data = new String(System.in.readAllBytes(), StandardCharsets.ISO_8859_1);
        if (data.indexOf('\r') >= 0) data = data.replace("\r\n", "\n").replace('\r', '\n');
        if (data.endsWith("\n")) data = data.substring(0, data.length() - 1);
        ArrayList<String> lines = new ArrayList<>();
        for (int start = 0;;) {
            int end = data.indexOf('\n', start);
            if (end < 0) { lines.add(data.substring(start)); break; }
            lines.add(data.substring(start, end));
            start = end + 1;
        }
        long n = Long.parseLong(lines.get(0).trim());
        int last = (int) Math.min(lines.size(), 1 + n);
        HashMap<String, Integer> counts = new HashMap<>(2 * last);
        for (int i = 1; i < last; i++) counts.merge(lines.get(i), 1, Integer::sum);
        String answer = "";
        for (int i = 1; i < last; i++) {
            if (counts.get(lines.get(i)) == 1) { answer = lines.get(i); break; }
        }
        OutputStream out = new BufferedOutputStream(System.out);
        out.write((answer + "\n").getBytes(StandardCharsets.ISO_8859_1));
        out.flush();
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
	"strings"
)

func main() {
	raw, _ := io.ReadAll(os.Stdin)
	data := string(raw)
	// Treat CRLF and lone CR as newlines, like text-mode input.
	if strings.IndexByte(data, '\r') >= 0 {
		data = strings.ReplaceAll(strings.ReplaceAll(data, "\r\n", "\n"), "\r", "\n")
	}
	data = strings.TrimSuffix(data, "\n")
	lines := strings.Split(data, "\n")
	n, _ := strconv.Atoi(strings.TrimSpace(lines[0]))
	last := min(len(lines), 1+n)
	logs := lines[1:last]
	counts := make(map[string]int, len(logs))
	for _, line := range logs {
		counts[line]++
	}
	answer := ""
	for _, line := range logs {
		if counts[line] == 1 {
			answer = line
			break
		}
	}
	w := bufio.NewWriter(os.Stdout)
	w.WriteString(answer)
	w.WriteByte('\n')
	w.Flush()
}
